  static BooleanNode booleanNode(String input){String v=input.trim();while(v.startsWith("(")&&outerParens(v))v=v.substring(1,v.length()-1).trim();for(String op:List.of("OR","AND")){List<String> pieces=booleanParts(v,op);if(pieces.size()>1){List<BooleanNode> nodes=new ArrayList<>();for(String part:pieces){BooleanNode n=booleanNode(part);if(n.kind.equals(op))nodes.addAll(n.children);else nodes.add(n);}return new BooleanNode(op,nodes,null);}}return new BooleanNode("ATOM",List.of(),v.replaceAll("\\s+",""));}
