    String script="$ErrorActionPreference='Stop'; $links=@(Get-NetTCPConnection -State Established -ErrorAction Stop | Where-Object { $_.RemotePort -eq 5236 -or $_.LocalPort -eq 5236 }); 'DM8SOCKETS='+$links.Count; foreach($link in $links){$link.LocalAddress+'|'+$link.LocalPort+'|'+$link.RemoteAddress+'|'+$link.RemotePort+'|'+$link.OwningProcess}";
