    for(String table:List.of("PROJECT","PROJECT_FILE","PROJECT_FILE_PARSE_RESULT","SYS_USER",AUDIT,"PROJECT_FACT_EXTRACTION_ATTEMPT","CONTRACT_REVIEW_STEP_ATTEMPT"))if(!cat.tables().containsKey(table))throw new IllegalStateException("BASELINE_SCHEMA_REQUIRED_TABLE_MISSING");
